#include "pause_menu_lua.hpp"
namespace mcl {
namespace {
// Lua long-bracket literal that cannot be closed early by the content.
std::string longString(const std::string& s){
 std::string eq;
 while(s.find("]"+eq+"]")!=std::string::npos)eq+="=";
 return "["+eq+"["+s+"]"+eq+"]";
}
const char* kBody=R"LUA(
-- Marvel: Crossover Legacy pause menu (generated by the frontend for this launch).
local machine = manager.machine
local ioport = machine.ioport
local container = machine.render.ui_container
local types = {}
for _, tok in ipairs({"START1", "COIN1", "P1_JOYSTICK_UP", "P1_JOYSTICK_DOWN",
                      "P1_JOYSTICK_LEFT", "P1_JOYSTICK_RIGHT", "P1_BUTTON1", "P1_BUTTON2"}) do
  types[tok] = ioport:token_to_input_type(tok)
end
local frame = 0
local function pressed(tok)
  if MCL_TEST_PRESSED then return MCL_TEST_PRESSED(tok, frame) end
  return ioport:type_pressed(types[tok], 0)
end
local state, cursor, combo, armed, flash = "play", 1, 0, false, 0
local held = {}
local function edge(tok)
  local now = pressed(tok)
  local was = held[tok]
  held[tok] = now
  return now and not was
end
local function resume() state = "play"; combo = 0; emu.unpause() end

local WHITE, GOLD, GREY = 0xffffffff, 0xffffd040, 0xffa0a8c0
local function item(y, label, selected)
  container:draw_text("center", y, selected and (">  " .. label .. "  <") or label,
                      selected and GOLD or GREY, 0)
end
-- draw_box(left, top, right, bottom, outline colour, fill colour)
local function panel(title)
  container:draw_box(0, 0, 1, 1, 0x00000000, 0xb0000008)
  container:draw_box(0.28, 0.30, 0.72, 0.70, GOLD, 0xf0101830)
  container:draw_text("center", 0.35, title, WHITE, 0)
end

emu.register_frame_done(function()
  frame = frame + 1
  if frame == 1 and MCL_READY_FILE ~= "" then
    local rf = io.open(MCL_READY_FILE, "w")
    if rf then rf:write("ready\n"); rf:close() end
  end
  -- read every edge each frame so "held" stays current
  local eu, el = edge("P1_JOYSTICK_UP"), edge("P1_JOYSTICK_LEFT")
  local ed, er = edge("P1_JOYSTICK_DOWN"), edge("P1_JOYSTICK_RIGHT")
  local up, down = eu or el, ed or er
  local ok = edge("P1_BUTTON1")
  local back = edge("P1_BUTTON2")
  local start = edge("START1")
  local startHeld, coinHeld = pressed("START1"), pressed("COIN1")

  if state == "play" then
    if startHeld and coinHeld then combo = combo + 1 else combo = 0 end
    if combo >= 9 then state, cursor, armed = "menu", 1, false; emu.pause() end
    return
  end
  if state == "flash" then
    flash = flash + 1
    local a = math.max(0, 255 - flash * 10)
    container:draw_box(0, 0, 1, 1, 0x00000000, (a << 24) | 0xffffff)
    if flash >= 26 then machine:exit() end
    return
  end
  -- ignore the opening START + SELECT until both are released
  if not armed then
    if not startHeld and not coinHeld then armed = true end
    ok, back, start, up, down = false, false, false, false, false
  end
  if state == "menu" then
    panel("PAUSED")
    item(0.47, "CONTINUE", cursor == 1)
    item(0.56, "EXIT GAME", cursor == 2)
    if up or down then cursor = 3 - cursor end
    if back then resume()
    elseif ok or start then
      if cursor == 1 then resume() else state, cursor = "confirm", 2 end
    end
  elseif state == "confirm" then
    panel("ARE YOU SURE?")
    item(0.47, "YES", cursor == 1)
    item(0.56, "NO", cursor == 2)
    if up or down then cursor = 3 - cursor end
    if back then resume()
    elseif ok or start then
      if cursor == 2 then resume()
      else
        local f = io.open(MCL_SIGNAL_FILE, "w")
        if f then f:write("exit\n"); f:close() end
        state, flash = "flash", 0
      end
    end
  end
end)
)LUA";
}
std::string buildPauseMenuLua(const std::string& signalFileUtf8,const std::string& readyFileUtf8){
 return "MCL_SIGNAL_FILE = "+longString(signalFileUtf8)+"\nMCL_READY_FILE = "+longString(readyFileUtf8)+"\n"+kBody;
}
}
